assignment.solutionCode:
class TrainingDummy {
  constructor() {
    this.hitCount = 0;
  }

  hit() {
    this.hitCount += 1;
  }
}

function runTraining() {
  const dummy = new TrainingDummy();
  dummy.hit();
  dummy.hit();
  dummy.hitCount = 10;
  dummy.hit();
  console.log(dummy.hitCount);
}

